import React, { useEffect, useRef, useCallback } from 'react';
import { useApp } from '../context/AppContext';

const API = 'http://localhost:5050';

export default function DicomViewer() {
  const { currentPatient, currentStudy, currentSeries, fileCount, sliceIndex, setSliceIndex } = useApp();

  const divRef = useRef(null);
  const engineRef = useRef(null);
  const viewportRef = useRef(null);
  const toolGroupRef = useRef(null);
  const csModulesRef = useRef(null);
  const mountedRef = useRef(true);

  const initCs = useCallback(async () => {
    if (!divRef.current) return;
    try {
      const [csCore, csTools] = await Promise.all([
        import('@cornerstonejs/core'),
        import('@cornerstonejs/tools'),
      ]);
      csModulesRef.current = { csCore, csTools };

      const { RenderingEngine, Enums } = csCore;
      const {
        ToolGroupManager, WindowLevelTool, ZoomTool, PanTool,
        StackScrollMouseWheelTool, Enums: ToolEnums,
      } = csTools;

      const engine = new RenderingEngine('sarcomaEngine');
      engineRef.current = engine;

      const viewportInput = {
        viewportId: 'sarcomaViewport',
        type: Enums.ViewportType.STACK,
        element: divRef.current,
        defaultOptions: { background: [0, 0, 0] },
      };
      engine.setViewports([viewportInput]);

      const viewport = engine.getViewport('sarcomaViewport');
      viewportRef.current = viewport;

      let tg = ToolGroupManager.getToolGroup('sarcomaGroup');
      if (!tg) {
        tg = ToolGroupManager.createToolGroup('sarcomaGroup');
        tg.addTool(WindowLevelTool.toolName);
        tg.addTool(ZoomTool.toolName);
        tg.addTool(PanTool.toolName);
        tg.addTool(StackScrollMouseWheelTool.toolName);
        tg.setToolActive(WindowLevelTool.toolName, { bindings: [{ mouseButton: ToolEnums.MouseBindings.Primary }] });
        tg.setToolActive(ZoomTool.toolName, { bindings: [{ mouseButton: ToolEnums.MouseBindings.Secondary }] });
        tg.setToolActive(PanTool.toolName, { bindings: [{ mouseButton: ToolEnums.MouseBindings.Auxiliary }] });
        tg.setToolActive(StackScrollMouseWheelTool.toolName);
      }
      tg.addViewport('sarcomaViewport', 'sarcomaEngine');
      toolGroupRef.current = tg;

      const { eventTarget } = csCore;
      const { Events } = Enums;
      const handleNewImage = (e) => {
        if (!mountedRef.current) return;
        const { newImageIdIndex } = e.detail;
        setSliceIndex(newImageIdIndex);
      };
      divRef.current.addEventListener(Events.STACK_NEW_IMAGE, handleNewImage);
    } catch (err) {
      console.warn('Cornerstone init error:', err);
    }
  }, [setSliceIndex]);

  useEffect(() => {
    mountedRef.current = true;
    initCs();
    return () => {
      mountedRef.current = false;
      try {
        if (toolGroupRef.current) {
          toolGroupRef.current.removeViewports('sarcomaEngine');
        }
        if (engineRef.current) {
          engineRef.current.destroy();
          engineRef.current = null;
        }
      } catch {}
    };
  }, [initCs]);

  useEffect(() => {
    if (!currentPatient || !currentStudy || !currentSeries || fileCount === 0) return;
    if (!viewportRef.current) return;

    const imageIds = [];
    for (let i = 0; i < fileCount; i++) {
      imageIds.push(
        `wadouri:${API}/api/dicom-file?patient=${currentPatient}/${currentStudy}&series=${currentSeries}&index=${i}`
      );
    }

    viewportRef.current.setStack(imageIds).then(() => {
      viewportRef.current.render();
    }).catch(console.warn);
  }, [currentPatient, currentStudy, currentSeries, fileCount]);

  const hasContent = currentPatient && currentStudy && currentSeries;

  return (
    <div style={{
      flex: 1,
      background: '#000',
      position: 'relative',
      overflow: 'hidden',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
    }}>
      <div
        ref={divRef}
        style={{
          width: '100%',
          height: '100%',
          display: hasContent ? 'block' : 'none',
        }}
      />

      {!hasContent && (
        <div style={{
          color: 'var(--text-secondary)',
          fontSize: 14,
          textAlign: 'center',
        }}>
          <div style={{ fontSize: 32, marginBottom: 12, opacity: 0.3 }}>◫</div>
          Select a series from the sidebar
        </div>
      )}

      {hasContent && (
        <>
          <div style={{
            position: 'absolute',
            top: 10,
            left: 12,
            color: 'rgba(255,255,255,0.3)',
            fontSize: 11,
            pointerEvents: 'none',
            fontFamily: 'monospace',
          }}>
            LDrag:W/L · RDrag:Zoom · MDrag:Pan · Scroll:Slice
          </div>

          <div style={{
            position: 'absolute',
            bottom: 12,
            left: '50%',
            transform: 'translateX(-50%)',
            background: 'rgba(0,0,0,0.5)',
            borderRadius: 4,
            padding: '3px 10px',
            color: 'rgba(255,255,255,0.7)',
            fontSize: 12,
            fontFamily: 'monospace',
            pointerEvents: 'none',
          }}>
            {sliceIndex + 1} / {fileCount}
          </div>
        </>
      )}
    </div>
  );
}
